verifyQuery:
run: order_items -> {
  where: created_at ? @2022
  group_by: mo is created_at.month
  aggregate: sales is sale_price.sum()
} extend {
  join_many: earlier is order_items -> {
    where: created_at ? @2022
    group_by: mo is created_at.month
    aggregate: sales is sale_price.sum()
  } on earlier.mo <= mo
} -> {
  group_by: mo
  aggregate:
    cume is earlier.sales.sum()
    month_sales is sales.sum()
} -> {
  where: cume >= 4000000
  select:
    crossing_month is month(mo)
    cume_at_crossing is round(cume, 2)
    prev_month_cume is round(cume - month_sales, 2)
    short_of_4m_prior_month is round(4000000 - (cume - month_sales), 2)
  order_by: crossing_month asc
  limit: 1
}
